import { JSDOM } from 'jsdom';
import fs from 'fs';
const dom = new JSDOM('<!DOCTYPE html><body></body>', { pretendToBeVisual: true });
global.window = dom.window; global.document = dom.window.document;
global.navigator = dom.window.navigator; global.DOMPurify = undefined;
const mermaid = (await import('mermaid')).default;
mermaid.initialize({ startOnLoad: false });
const files = process.argv.slice(2);
let bad = 0;
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  const blocks = [...src.matchAll(/```mermaid\n([\s\S]*?)```/g)];
  blocks.forEach((m, i) => {
    try { mermaid.parse(m[1]); console.log(`OK   ${f} #${i+1}`); }
    catch (e) { bad++; console.log(`FAIL ${f} #${i+1}: ${String(e.message||e).split('\n').slice(0,4).join(' | ')}`); }
  });
}
process.exit(bad ? 1 : 0);
